rows = [dict(zip(COLUMNS, (f"KTA-{index:03d}",) + finding)) for index, finding in enumerate(FINDINGS, 1)]
for row in rows:
    assert len(row) == len(COLUMNS), row["Finding_ID"]

output = Path(__file__).resolve().parent.parent / "docs" / "total-audit" / "KHALSNI_TOTAL_FINDINGS.csv"
with output.open("w", newline="", encoding="utf-8") as handle:
    writer = csv.DictWriter(handle, fieldnames=COLUMNS)
    writer.writeheader()
    writer.writerows(rows)

closed = {"FIXED", "PASS"}
summary = collections.OrderedDict((s, [0, 0, 0]) for s in ("CRITICAL", "HIGH", "MEDIUM", "LOW", "INFO"))
for row in rows:
    entry = summary[row["Severity"]]
    entry[0] += 1
    entry[1 if row["Fix_Status"] in closed else 2] += 1
for severity, (found, fixed, still_open) in summary.items():
    print(f"{severity}: found {found}, fixed {fixed}, open {still_open}")
for row in rows:
    if row["Fix_Status"] not in closed:
        print(row["Finding_ID"], row["Severity"], row["Fix_Status"], "-", row["Title"])
